/* 全站共用导航栏 — 由 scripts/extract_nav.mjs 生成。
   以前这段 HTML + CSS 在 32 个页面里各存一份;要加登录态 / 用户菜单 /
   登出按钮,现在只改这一支。

   刻意用 classic <script>(没有 defer / async):它在解析到该位置时【同步】
   执行,导航在后面任何脚本跑之前就已经进 DOM。页面里的 scroll-spy 与
   admin 解锁都靠 getElementById('globalNav') 找它,顺序不能错。 */
(function () {
  var LOGO = 'data:image/jpeg;base64,';

  var CSS = ".navbar{position:fixed;top:0;left:0;right:0;z-index:95;\n  display:flex;align-items:center;justify-content:space-between;\n  gap:12px;padding:10px clamp(14px,3vw,28px);\n  background:rgba(10,10,14,.55);\n  -webkit-backdrop-filter:blur(18px) saturate(160%);\n  backdrop-filter:blur(18px) saturate(160%);\n  border-bottom:1px solid rgba(232,200,119,.14);\n  box-shadow:0 1px 0 rgba(255,255,255,.04) inset, 0 8px 32px rgba(0,0,0,.18);\n  font-family:'JetBrains Mono',ui-monospace,monospace;}\n.navbar .nb-brand{display:flex;align-items:center;gap:10px;text-decoration:none;flex-shrink:0;}\n.navbar .nb-brand img{height:30px;width:auto;border-radius:6px;}\n.navbar .nb-brand .nb-name{font-size:11px;font-weight:700;letter-spacing:.14em;color:var(--text);text-transform:uppercase;}\n.navbar .nb-links{display:flex;align-items:center;gap:2px;flex-wrap:nowrap;}\n.navbar .nb-links a{font-family:'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;\n  color:var(--muted);text-decoration:none;padding:6px 12px;border-radius:16px;transition:.25s;white-space:nowrap;}\n.navbar .nb-links a:hover{color:var(--gold-bright);background:rgba(232,200,119,.08);}\n.navbar .nb-links a.active{color:var(--gold-bright);border:1px solid rgba(232,200,119,.35);background:rgba(232,200,119,.1);}\n.navbar .nb-right{display:flex;align-items:center;gap:8px;flex-shrink:0;}\n.navbar .nb-lang{display:flex;align-items:center;gap:4px;background:rgba(232,200,119,.08);border:1px solid rgba(232,200,119,.2);border-radius:20px;padding:3px;}\n.navbar .nb-lang button{background:none;border:none;color:var(--muted);font-family:'JetBrains Mono',monospace;\n  font-size:10px;letter-spacing:.08em;padding:4px 10px;border-radius:16px;cursor:pointer;transition:.2s;}\n.navbar .nb-lang button.on{color:var(--gold-bright);background:rgba(232,200,119,.18);}\n@media(max-width:640px){\n  .navbar{flex-wrap:wrap;padding:8px 10px;gap:6px;}\n  .navbar .nb-brand .nb-name{display:none;}\n  .navbar .nb-links{order:3;width:100%;justify-content:center;gap:0;}\n  .navbar .nb-links a{font-size:9px;padding:5px 8px;letter-spacing:.1em;}\n  .navbar .nb-right{margin-left:auto;}\n}\n/* 英文标签比中文长得多,375px 下五个链接排不开,原本是直接被切掉两头\n   (每一页都这样,不是登录页带来的)。允许换行,别裁。 */\n@media(max-width:640px){\n  .navbar .nb-links{flex-wrap:wrap;row-gap:2px;}\n  .navbar .nb-links a{padding:5px 7px;}\n}\n/* 登录入口。放在语言切换旁边而不是链接区 —— 账号操作不是内容分区,\n   混进去会让「当前在哪一节」的高亮逻辑说不清。\n   认证做好之后,这颗按钮换成用户菜单(头像 / 我的课程 / 登出)。 */\n.navbar .nb-auth{font-family:'JetBrains Mono',monospace;font-size:10px;\n  letter-spacing:.14em;text-transform:uppercase;font-weight:700;\n  color:var(--gold);text-decoration:none;white-space:nowrap;\n  padding:6px 14px;border-radius:20px;\n  border:1px solid rgba(232,200,119,.34);background:rgba(232,200,119,.06);\n  transition:.22s;}\n.navbar .nb-auth:hover{color:#0A0A0E;background:var(--gold);border-color:var(--gold);}\n.navbar .nb-auth[aria-current=\"page\"]{color:var(--gold-bright);\n  background:rgba(232,200,119,.16);border-color:rgba(232,200,119,.5);}\n@media(max-width:640px){\n  .navbar .nb-auth{font-size:9px;padding:5px 10px;letter-spacing:.1em;}\n}\n/* nb-mid-tight —— 641px 到 1200px 之间,英文标签排不下,右边的登录与\n   语言切换会被挤出画面。这一段收紧字距与内距,并把品牌文字收起来\n   (图标还在,认得出是谁)。中文模式标签短,本来就排得下。 */\n@media(min-width:641px) and (max-width:1200px){\n  .navbar{padding:10px 14px;gap:8px;}\n  .navbar .nb-brand .nb-name{display:none;}\n  .navbar .nb-links{gap:0;min-width:0;}\n  .navbar .nb-links a{font-size:9.5px;letter-spacing:.09em;padding:6px 7px;}\n  .navbar .nb-auth{font-size:9.5px;padding:5px 11px;letter-spacing:.1em;}\n}\n/* nb-tiny —— 375px 下六个项目会挤成三行(整条 109px 高),把封面往下压掉\n   一大截。再收一档字距与内距,回到两行。 */\n@media(max-width:430px){\n  .navbar{padding:6px 8px;gap:4px;}\n  .navbar .nb-links{gap:0;row-gap:1px;}\n  .navbar .nb-links a{font-size:8.5px;letter-spacing:.05em;padding:4px 5px;}\n  .navbar .nb-auth{font-size:8.5px;padding:4px 8px;letter-spacing:.06em;}\n  .navbar .nb-lang button{font-size:9px;padding:3px 7px;}\n}";

  /* 从自己的 src 反推站点根目录 —— 页面在第几层都不必改。
     用字符串切,不用正则:这支档是模板字符串产生的,正则的反斜杠会被吃掉一层。 */
  var me = document.currentScript;
  var ROOT = me.src.slice(0, me.src.lastIndexOf('assets/nav.js'));

  /* ===== beta 开关 =====
     登录入口露出来,但登录页自己盖着 COMING SOON —— 学生看得到「以后
     要登录」这件事,点进去知道还没开放。收费时把登录页末尾那段遮罩
     脚本删掉即可,这里不用再动。 */
  var SHOW_AUTH = true;

  var ITEMS = [
    ['home',    'MakeTradesJourney.html#top', 'Home',            '首页'],
    ['courses', 'courses.html',               'Trading Courses', '交易课程'],
    ['advanced','advanced.html',              'Advanced Trading Course', '进阶交易课程'],
    ['ea',      'ea.html',                    'EA Courses',      'EA 课程'],
    ['tools',   'tools.html',                 'Tools',           '工具'],
    ['about',   'about.html',                 'About',           '关于']
  ];
  var SELF = { home:'MakeTradesJourney.html', courses:'courses.html',
               advanced:'advanced.html',
               ea:'ea.html', tools:'tools.html', about:'about.html' };


  /* ===== 模块编号迁移 v2 =====
     2026-08 把交易课程重排成 1-19、进阶 20-26、EA 27,并下架了平台课。
     mtj_exam_pass_N 是学员的通过纪录,编号一动就对不上,所以在这里做一次
     性映射。放 nav.js 是因为它全站共用,而且比各页的解锁逻辑先跑。
     旧 25 同时被枢轴点与 EA 用过(撞号),取存在比较久的 EA。 */
  try {
    if (localStorage.getItem('mtj_renum_v2') !== '1') {
      var REMAP = { 1:1, 2:2, 3:3, 4:4, 5:12, 6:13, 7:18, 8:15, 9:5, 10:19,
                    11:17, 12:8, 13:9, 14:10, 15:6, 16:7, 17:20, 18:21,
                    19:22, 20:23, 21:24, 22:25, 23:26, 25:27, 26:14, 27:11 };
      var passed = [];
      for (var k in REMAP) {
        if (localStorage.getItem('mtj_exam_pass_' + k) === '1') passed.push(REMAP[k]);
      }
      /* 先清掉旧的整段,再写新的 —— 新旧号码会互相覆盖,不能就地改 */
      for (var i = 1; i <= 27; i++) localStorage.removeItem('mtj_exam_pass_' + i);
      for (var j = 0; j < passed.length; j++) {
        localStorage.setItem('mtj_exam_pass_' + passed[j], '1');
      }
      localStorage.setItem('mtj_renum_v2', '1');
    }
  } catch (e) {}

  /* ===== 模块编号迁移 v3 =====
     「均线 · 支撑阻力」拆成两门:均线留在 5,支撑与阻力新增为 15(阶段 05
     最前面),所以 15 以後全部往後挪一格。v2 已经把大家正规化到旧的编号,
     这里只要在它之上再做一次 +1。
     旧 5 是那门合并课,通过纪录留给均线(主题以它为主),支撑与阻力从头开始。 */
  try {
    if (localStorage.getItem('mtj_renum_v3') !== '1') {
      var moved = [];
      for (var q = 27; q >= 15; q--) {
        if (localStorage.getItem('mtj_exam_pass_' + q) === '1') moved.push(q + 1);
        localStorage.removeItem('mtj_exam_pass_' + q);
      }
      for (var r = 0; r < moved.length; r++) {
        localStorage.setItem('mtj_exam_pass_' + moved[r], '1');
      }
      localStorage.setItem('mtj_renum_v3', '1');
    }
  } catch (e) {}

  /* ===== 模块编号迁移 v4 =====
     学习顺序改成「价格优先、指标最後」:指标原本排在第 5-11,小白还没学会
     看一根 K 线就先学了七门指标,而课程页自己写着「指标只用来确认价格」。
     顺带解掉两个前置依赖(背离要会认摆动结构、一目不再是第七门课)。
     接在 v3 之後,只做一次位置对调。 */
  try {
    if (localStorage.getItem('mtj_renum_v4') !== '1') {
      var R4 = { 5:14, 6:15, 7:16, 8:17, 9:18, 10:19, 11:20,
                 12:5, 13:6, 14:7, 15:8, 16:9, 17:10, 18:11, 19:12, 20:13 };
      var keep = [];
      for (var a = 5; a <= 20; a++) {
        if (localStorage.getItem('mtj_exam_pass_' + a) === '1') keep.push(R4[a]);
        localStorage.removeItem('mtj_exam_pass_' + a);
      }
      for (var b = 0; b < keep.length; b++) {
        localStorage.setItem('mtj_exam_pass_' + keep[b], '1');
      }
      localStorage.setItem('mtj_renum_v4', '1');
    }
  } catch (e) {}
  var pathn = location.pathname;
  var here  = pathn.slice(pathn.lastIndexOf('/') + 1) || 'MakeTradesJourney.html';

  /* 当前页归属哪一节 —— 课程内页归「交易课程」,工具内页归「工具」,
     backtest 是从 EA 课程链过去的,归「EA 课程」 */
  var inDir = function (d) { return pathn.indexOf('/' + d + '/') > -1; };
  var cur = (here === 'advanced.html')                        ? 'advanced'
          : (inDir('courses') || here === 'courses.html') ? 'courses'
          : (inDir('tools')   || here === 'tools.html')   ? 'tools'
          : (here === 'ea.html' || here === 'backtest.html') ? 'ea'
          : (here === 'about.html')                          ? 'about'
          /* login 之类的独立页不属于任何一节 —— 与其点亮「首页」误导,
             不如一个都不点 */
          : (here === 'MakeTradesJourney.html' || here === '') ? 'home'
          : '';

  var links = ITEMS.map(function (it) {
    /* 指向自己时用 #top:与原本一致,scroll-spy 靠「href 以 # 开头」判断同页锚点 */
    var href = (SELF[it[0]] === here) ? '#top' : ROOT + it[1];
    return '<a href="' + href + '" data-sec="' + it[0] + '"' +
           (it[0] === cur ? ' class="active"' : '') +
           '>· ' + it[2] + ' <span class="zh">· ' + it[3] + '</span></a>';
  }).join('');

  var brand = (here === 'MakeTradesJourney.html') ? '#top' : ROOT + 'MakeTradesJourney.html#top';

  /* 样式插在 <head> 最前面:页面自己的样式仍然盖得过它,
     和原本写在页面 <style> 里的效果一致 */
  var st = document.createElement('style');
  st.setAttribute('data-mtj', 'nav');
  st.textContent = CSS;
  document.head.insertBefore(st, document.head.firstChild);

  me.insertAdjacentHTML('beforebegin',
    '<nav class="navbar" id="globalNav">' +
      '<a class="nb-brand" href="' + brand + '">' +
        '<img src="' + LOGO + '" alt="Make Trades Journey">' +
        '<span class="nb-name">Make Trades Journey</span>' +
      '</a>' +
      '<div class="nb-links">' + links + '</div>' +
      '<div class="nb-right">' +
        (SHOW_AUTH
          ? '<a class="nb-auth" href="' + (here === 'login.html' ? '#top' : ROOT + 'login.html') + '"' +
            (here === 'login.html' ? ' aria-current="page"' : '') +
            '>Sign in <span class="zh">登录</span></a>'
          : '') +
        '<div class="nb-lang">' +
        '<button id="langEn">EN</button>' +
        '<button id="langZh">中</button>' +
      '</div></div>' +
    '</nav>');

  /* 语言按钮插入后再绑事件,不写行内 onclick —— 行内写法的引号经过模板
     字符串会被吃掉一层。setLang 由各页定义在后面,点下去时早就存在了。 */
  document.getElementById('langEn').onclick = function () { window.setLang('en'); };
  document.getElementById('langZh').onclick = function () { window.setLang('zh'); };
})();
